formal_cold_pilot.source:
adsp_cold_pilot_mapped(vm_offset_t destination)
{
    if(!adsp_fw_expanded || !adsp_fw_metadata || !adsp_fw_metadata_pa)return 40;
    struct adsp_rw_map map={0};map.private_offset=adsp_last_private_offset;map.private_bytes=adsp_last_private_bytes;
    map.private_page=map.private_offset&~0x3fffu;
    map.private=ml_io_map(0x86000000u+map.private_page,(map.private_offset-map.private_page+map.private_bytes+0x3fffu)&~0x3fffu);
    if(!map.private)return 42;
    adsp_power_attempted=1;
    int level=sweet_rpm_request(0x61706d73u,1u,0x6c766c76u,384u,0u);
    int sleep=level==0?sweet_rpm_request(0x61706d73u,1u,0x6c766c76u,384u,1u):-99;
    printf("SWEET ADSP COLD PROXY level=%d sleep=%d retained=1\n",level,sleep);
    if(level || sleep)return 43;
    int clocks=sweet_rpm_vote_gpu_clocks();printf("SWEET ADSP COLD CLOCKS result=%d\n",clocks);if(clocks)return 44;
    /* DT logical master55->RPM23, slave512->RPM0; RPM BW is sum_ab, not IB. */
    int b0=sweet_rpm_bus_request(0x73616d62u,23u,393600000ull,0u);
    int b1=b0==0?sweet_rpm_bus_request(0x73616d62u,23u,393600000ull,1u):-99;
    int s0=b0==0&&b1==0?sweet_rpm_bus_request(0x766c7362u,0u,393600000ull,0u):-99;
    int s1=b0==0&&b1==0&&s0==0?sweet_rpm_bus_request(0x766c7362u,0u,393600000ull,1u):-99;
    printf("SWEET ADSP COLD BANDWIDTH master=%d/%d slave=%d/%d\n",b0,b1,s0,s1);
    if(b0||b1||s0||s1)return 45;
    adsp_flush_virtual((vm_offset_t)adsp_fw_metadata,ADSP_MDT_BYTES,"metadata");
    printf("SWEET ADSP COLD INIT_BEGIN pas_id=1 metadata=%#llx bytes=%u at_ms=%llu\n",
        (unsigned long long)adsp_fw_metadata_pa,ADSP_MDT_BYTES,(unsigned long long)boot_ms());
    uint64_t value=0;int64_t call=sweet_adsp_pil_command(1,adsp_fw_metadata_pa,&value);
    printf("SWEET ADSP COLD INIT result=%lld value=%llu\n",(long long)call,(unsigned long long)value);
    if(call || value)return 50;
    printf("SWEET ADSP COLD MEMORY_BEGIN base=%#x bytes=%u at_ms=%llu\n",
        ADSP_RESERVED_BASE,ADSP_RAW_BYTES,(unsigned long long)boot_ms());
    call=sweet_adsp_pil_command(2,0,&value);
    printf("SWEET ADSP COLD MEMORY result=%lld value=%llu base=%#x bytes=%u\n",(long long)call,
        (unsigned long long)value,ADSP_RESERVED_BASE,ADSP_RAW_BYTES);
    if(call || value)return 51;
    printf("SWEET ADSP COLD COPY_BEGIN base=%#x bytes=%u at_ms=%llu\n",
        ADSP_RESERVED_BASE,ADSP_RAW_BYTES,(unsigned long long)boot_ms());
    memcpy((void *)destination,(const void *)adsp_fw_expanded,ADSP_RAW_BYTES);
    adsp_flush_virtual(destination,ADSP_RAW_BYTES,"firmware");
    __asm__ volatile("dsb sy" ::: "memory");
    uint64_t hash=adsp_fnv(14695981039346656037ull,(const uint8_t *)destination,ADSP_RAW_BYTES);
    printf("SWEET ADSP COLD COPY bytes=%u fnv=%016llx verified=%u\n",ADSP_RAW_BYTES,(unsigned long long)hash,hash==ADSP_RAW_FNV);
    if(hash!=ADSP_RAW_FNV)return 52;
    unsigned authenticated=0,ready=0;uint32_t slave=0;int result;
    printf("SWEET ADSP COLD AUTH_BEGIN pas_id=1 at_ms=%llu\n",(unsigned long long)boot_ms());
    call=sweet_adsp_pil_command(5,0,&value);authenticated=call==0 && value==0;adsp_auth_succeeded=authenticated;
    printf("SWEET ADSP COLD AUTH result=%lld value=%llu\n",(long long)call,(unsigned long long)value);
    if(authenticated)printf("SWEET ADSP COLD READY_BEGIN timeout_ms=10000 at_ms=%llu\n",(unsigned long long)boot_ms());
    result=authenticated?adsp_wait_private_ready(&map,10000,&slave):53;ready=result==0;adsp_ready_observed=ready;
    printf("SWEET ADSP COLD READY observed=%u result=%d slave=%#x\n",ready,result,slave);
    int profile=0;PE_parse_boot_argn("sweetadspboot",&profile,sizeof(profile));
    if(ready && profile==5)result=adsp_glink_negotiate(&map);
    if(ready && (profile==6 || profile==7))result=adsp_apr_probe(&map,profile==7);
    printf("SWEET ADSP COLD SHUTDOWN_BEGIN pas_id=1 at_ms=%llu\n",(unsigned long long)boot_ms());
    uint64_t shut_value=0;int64_t shut=sweet_adsp_pil_command(6,0,&shut_value);
    printf("SWEET ADSP COLD SHUTDOWN result=%lld value=%llu\n",(long long)shut,(unsigned long long)shut_value);
    adsp_shutdown_ok=shut==0&&shut_value==0;
    if(profile==6 || profile==7)adsp_apr_finish(adsp_shutdown_ok);
    if(shut || shut_value)result=74;
    printf("SWEET ADSP COLD END result=%d authenticated=%u ready_observed=%u stopped=%u audio_output_verified=0\n",
        result,authenticated,ready,shut==0&&shut_value==0);
    return result;
}

formal_bootstrap.source:
adsp_bootstrap_once(void)
{
    static unsigned attempted;int stage=0,norpm=0;
    PE_parse_boot_argn("sweetadspboot",&stage,sizeof(stage));PE_parse_boot_argn("sweetgpunorpm",&norpm,sizeof(norpm));
    if((stage!=3 && stage!=4 && stage!=5 && stage!=6 && stage!=7)||norpm!=1||attempted||get_system_inshutdown())return;
    attempted=1;printf("SWEET ADSP BEGIN stage=%d pas_id=1 power_writes=0 firmware_started=0\n",stage);
    if(!adsp_verify_bundle(stage>=4)){printf("SWEET ADSP END stage=%d result=10 verified=0 prepared=0\n",stage);return;}
    static const unsigned commands[]={1,2,5,6};unsigned available=0;
    for(unsigned i=0;i<(stage>=4?4u:3u);i++) {
        uint64_t value=0;int64_t result=sweet_pil_api_available(commands[i],&value);
        printf("SWEET ADSP API cmd=%u result=%lld available=%llu\n",commands[i],(long long)result,(unsigned long long)value);
        if(result==0 && value==1)available++;
    }
    int result=available==(stage>=4?4u:3u)?0:11,prepared=0;
    if(result==0){result=adsp_prepare_ap();prepared=result==0;}
    if(result==0 && stage>=4)result=adsp_cold_pilot();
    printf("SWEET ADSP END stage=%d result=%d verified=1 api_count=%u prepared=%d authenticated=%u ready_observed=%u stopped=%u power_requests=%u\n",
        stage,result,available,prepared,adsp_auth_succeeded,adsp_ready_observed,adsp_shutdown_ok,adsp_power_attempted);
    if(stage==5)printf("SWEET ADSP GLINK ACCEPT version_verified=%u apr_verified=0 audio_output_verified=0\n",adsp_glink_verified);
    if(stage==6)printf("SWEET ADSP APR ACCEPT response_verified=%u state=%u link_closed=%u audio_output_verified=0\n",adsp_apr_out.response_verified,adsp_apr_out.state,adsp_apr_out.glink_closed);
    if(stage==7)printf("SWEET ADSP APR LEGACY_ACCEPT response_verified=%u legacy_verified=%u generation=%u version_id=%#x link_closed=%u audio_output_verified=0\n",
        adsp_apr_out.response_verified,adsp_apr_out.legacy_verified,adsp_apr_out.legacy.generation,adsp_apr_out.legacy.version_id,adsp_apr_out.glink_closed);
    if (adsp_fw_expanded) { kmem_free(kernel_map,adsp_fw_expanded,ADSP_RAW_BYTES);adsp_fw_expanded=0; }
}

formal_clock_helper.source:
sweet_rpm_vote_gpu_clocks(void)
{
    int xo=-99,ce=-99,ag=-99;
    xo=sweet_rpm_request(0x306b6c63u,0u,0x62616e45u,1u,0u);
    if(xo==0)ce=sweet_rpm_request(0x00006563u,0u,0x007a484bu,sweet_rpm_rate_khz(85710000u),0u);
    if(xo==0 && ce==0)ag=sweet_rpm_request(0x72676761u,2u,0x007a484bu,sweet_rpm_rate_khz(300000000u),0u);
    printf("SWEET RPM: gpu clocks xo=%d ce=%d aggr2=%d (not-attempted=-99)\n",xo,ce,ag);
    return (xo || ce || ag)?-1:0;
}

formal_ready.source:
adsp_wait_private_ready(struct adsp_rw_map *map,unsigned milliseconds,uint32_t *last)
{
    struct sweet_smem_part part={.offset=map->private_offset,.size=map->private_bytes,.host0=0,.host1=2};
    uint64_t interval;nanoseconds_to_absolutetime((uint64_t)milliseconds*1000000ull,&interval);
    uint64_t deadline=mach_absolute_time()+interval;static uint32_t buffer[128];
    unsigned printed=0;
    while(mach_absolute_time()<deadline && !get_system_inshutdown()) {
        struct adsp_private_item item={0};int found=adsp_private_find(&part,adsp_rw_read,map,443,&item);
        if(found<0)return 70;
        if(found==1 && item.size>=20 && item.size<=sizeof(buffer) && !(item.size&3u)) {
            volatile uint32_t *p=adsp_rw_address(map,item.offset,item.size);
            if(!p)return 71;
            __asm__ volatile("dmb oshld" ::: "memory");
            for(unsigned i=0;i<item.size/4;i++)buffer[i]=p[i];
            struct sweet_smem_smp h={0};
            if(sweet_smem_smp_read((const uint8_t *)buffer,item.size,2,0,&h)) {
                for(unsigned i=0;i<h.valid;i++) {
                    const uint8_t *entry=(const uint8_t *)buffer+20+i*20;
                    if(!strncmp((const char *)entry,"slave-kernel",16)) {
                        uint32_t value=sweet_smem_u32(entry+16);*last=value;
                        if(printed<8){printf("SWEET ADSP COLD SLAVE value=%#x ready=%u fatal=%u proxy_unvote=%u\n",
                            value,!!(value&2u),!!(value&1u),!!(value&4u));printed++;}
                        if(value&1u)return 72;
                        if(value&2u)return 0;
                    }
                }
            }
        }
        delay(1000);
    }
    return 73;
}

